#include "hardwaretools.hpp"
#include "language.hpp"
#ifdef Q_OS_WIN
#define THINKCAD_PORT_ADDRESS(info) (info).portName()
#else
#define THINKCAD_PORT_ADDRESS(info) (info).systemLocation()
#endif
#include <QDialog>
#include <QFormLayout>
#include <QVBoxLayout>
#include <QHBoxLayout>
#include <QLineEdit>
#include <QComboBox>
#include <QPushButton>
#include <QPlainTextEdit>
#include <QLabel>
#include <QFileDialog>
#include <QSettings>
#include <QSerialPortInfo>
#include <QStandardPaths>
#include <QDir>
#include <QFile>
#include <QRegularExpression>
#include <stdexcept>
HardwareBuild::HardwareBuild(QObject* parent):QObject(parent){QObject::connect(&process_,&QProcess::readyReadStandardOutput,this,[this]{emit log(QString::fromUtf8(process_.readAllStandardOutput()));});QObject::connect(&process_,&QProcess::readyReadStandardError,this,[this]{emit log(QString::fromUtf8(process_.readAllStandardError()));});QObject::connect(&process_,qOverload<int,QProcess::ExitStatus>(&QProcess::finished),this,[this](int code,QProcess::ExitStatus status){bool ok=code==0&&status==QProcess::NormalExit;if(!uploading_)compiled_=ok;emit finished(ok);});QObject::connect(&process_,&QProcess::errorOccurred,this,[this](QProcess::ProcessError error){if(error==QProcess::FailedToStart){compiled_=false;emit log(process_.errorString());emit finished(false);}});}
HardwareBuild::~HardwareBuild(){cancel();}
QString HardwareBuild::suggestedFqbn(const std::string& model){if(model=="arduino-uno")return "arduino:avr:uno";if(model=="arduino-nano")return "arduino:avr:nano:cpu=atmega328old";if(model=="esp32")return "esp32:esp32:esp32";if(model=="esp32-s3")return "esp32:esp32:esp32s3";return "esp8266:esp8266:nodemcuv2";}
void HardwareBuild::cancel(){if(busy()){process_.kill();process_.waitForFinished(2000);}compiled_=false;}
void HardwareBuild::compile(const SketchProject& project,const QString& cli,const QString& fqbn,const QStringList& libraries){
    if(busy())throw std::runtime_error("A hardware operation is already running");if(cli.isEmpty()||!QRegularExpression("^[A-Za-z0-9_:.=,+-]+$").match(fqbn).hasMatch())throw std::runtime_error("Choose arduino-cli and a valid FQBN");compiled_=false;uploading_=false;temp_=std::make_unique<QTemporaryDir>();if(!temp_->isValid())throw std::runtime_error("Cannot create build directory");cli_=cli;fqbn_=fqbn;sketchPath_=temp_->filePath("ThinkCadSketch");buildPath_=temp_->filePath("build");QDir().mkpath(sketchPath_);QString ino;std::size_t bytes=0;
    for(const auto& name:project.order){if(!ProjectIO::validFileName(name)||!project.files.contains(name))throw std::runtime_error("Invalid sketch filename");auto data=project.files.value(name).toUtf8();bytes+=data.size();if(bytes>3*1024*1024)throw std::runtime_error("Sketch exceeds 3 MiB");if(name.endsWith(".ino",Qt::CaseInsensitive))ino+="\n#line 1 \""+name+"\"\n"+QString::fromUtf8(data)+"\n";else{QFile file(sketchPath_+"/"+name);if(!file.open(QIODevice::WriteOnly)||file.write(data)!=data.size())throw std::runtime_error("Cannot write sketch file");}}
    if(ino.isEmpty())throw std::runtime_error("Project has no .ino file");QFile primary(sketchPath_+"/ThinkCadSketch.ino");auto data=ino.toUtf8();if(!primary.open(QIODevice::WriteOnly)||primary.write(data)!=data.size())throw std::runtime_error("Cannot write primary sketch");primary.close();QStringList args{"compile","--fqbn",fqbn_,"--build-path",buildPath_,"--warnings","all"};for(const auto& library:libraries)args<<"--libraries"<<library;args<<sketchPath_;emit log(Language::text("Hardware-Sketch wird kompiliert…"));process_.start(cli_,args);
}
void HardwareBuild::upload(const QString& port){if(busy()||!compiled_||port.isEmpty())throw std::runtime_error("Compile successfully and select a port first");uploading_=true;emit log(Language::text("Firmware wird hochgeladen…"));process_.start(cli_,{"upload","--fqbn",fqbn_,"--port",port,"--input-dir",buildPath_,sketchPath_});}
void showHardwareTools(QWidget* parent,const SketchProject& project,const std::string& model,const QStringList& projectLibraries){QDialog dialog(parent);dialog.setObjectName("hardwareDialog");dialog.setWindowTitle(Language::text("Hardware kompilieren und hochladen"));dialog.resize(780,550);auto* layout=new QVBoxLayout(&dialog);auto* info=new QLabel(Language::text("Arduino CLI und passender Board-Core müssen installiert sein. Der komplette Sketch wird für echte Hardware gebaut. Upload schreibt das angeschlossene Board."));info->setWordWrap(true);layout->addWidget(info);auto* form=new QFormLayout;auto* cli=new QLineEdit(QSettings().value("arduinoCli",QStandardPaths::findExecutable("arduino-cli")).toString());cli->setObjectName("arduinoCliPath");auto* cliRow=new QWidget;auto* cliLayout=new QHBoxLayout(cliRow);cliLayout->setContentsMargins(0,0,0,0);cliLayout->addWidget(cli);auto* browse=new QPushButton("…");cliLayout->addWidget(browse);form->addRow("Arduino CLI",cliRow);auto* fqbn=new QLineEdit(QSettings().value("fqbn/"+QString::fromStdString(model),HardwareBuild::suggestedFqbn(model)).toString());fqbn->setObjectName("hardwareFqbn");form->addRow("FQBN",fqbn);auto* port=new QComboBox;port->setObjectName("uploadPort");port->setEditable(true);auto* portRow=new QWidget;auto* portLayout=new QHBoxLayout(portRow);portLayout->setContentsMargins(0,0,0,0);portLayout->addWidget(port);auto* refresh=new QPushButton(Language::text("Ports aktualisieren"));portLayout->addWidget(refresh);auto enumerate=[port]{auto selected=port->currentData().toString();if(selected.isEmpty())selected=port->currentText();port->clear();for(const auto& info:QSerialPortInfo::availablePorts())port->addItem(THINKCAD_PORT_ADDRESS(info),THINKCAD_PORT_ADDRESS(info));int index=port->findData(selected);if(index>=0)port->setCurrentIndex(index);else if(!selected.isEmpty())port->setEditText(selected);};enumerate();form->addRow(Language::text("Port"),portRow);layout->addLayout(form);auto* log=new QPlainTextEdit;log->setObjectName("hardwareLog");log->setReadOnly(true);layout->addWidget(log);auto* buttons=new QHBoxLayout;auto* compile=new QPushButton(Language::text("Kompilieren"));compile->setObjectName("hardwareCompile");auto* upload=new QPushButton(Language::text("Hochladen"));upload->setObjectName("hardwareUpload");upload->setEnabled(false);auto* cancel=new QPushButton(Language::text("Abbrechen"));auto* close=new QPushButton(Language::text("Schließen"));for(auto* b:{compile,upload,cancel,close})buttons->addWidget(b);layout->addLayout(buttons);HardwareBuild builder;QObject::connect(&builder,&HardwareBuild::log,log,&QPlainTextEdit::appendPlainText);QObject::connect(&builder,&HardwareBuild::finished,&dialog,[&](bool ok){compile->setEnabled(true);cli->setEnabled(true);fqbn->setEnabled(true);upload->setEnabled(builder.compiled());log->appendPlainText(Language::text(ok?"Vorgang erfolgreich abgeschlossen.":"Vorgang fehlgeschlagen. Ausgabe prüfen."));});QObject::connect(compile,&QPushButton::clicked,&dialog,[&]{try{QSettings().setValue("arduinoCli",cli->text());QSettings().setValue("fqbn/"+QString::fromStdString(model),fqbn->text());builder.compile(project,cli->text(),fqbn->text(),projectLibraries+QSettings().value("libraries").toStringList());compile->setEnabled(false);upload->setEnabled(false);cli->setEnabled(false);fqbn->setEnabled(false);}catch(const std::exception& e){log->appendPlainText(QString::fromUtf8(e.what()));}});QObject::connect(upload,&QPushButton::clicked,&dialog,[&]{try{builder.upload(port->currentText().trimmed());compile->setEnabled(false);upload->setEnabled(false);}catch(const std::exception& e){log->appendPlainText(QString::fromUtf8(e.what()));}});auto invalidate=[&]{upload->setEnabled(false);};QObject::connect(cli,&QLineEdit::textChanged,&dialog,invalidate);QObject::connect(fqbn,&QLineEdit::textChanged,&dialog,invalidate);QObject::connect(browse,&QPushButton::clicked,&dialog,[&]{auto path=QFileDialog::getOpenFileName(&dialog,Language::text("Arduino CLI wählen"));if(!path.isEmpty())cli->setText(path);});QObject::connect(refresh,&QPushButton::clicked,&dialog,enumerate);QObject::connect(cancel,&QPushButton::clicked,&dialog,[&]{builder.cancel();compile->setEnabled(true);cli->setEnabled(true);fqbn->setEnabled(true);upload->setEnabled(false);});QObject::connect(close,&QPushButton::clicked,&dialog,&QDialog::reject);dialog.exec();}
